import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.resolve(__dirname, 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description:
        'Return the relative path, byte size, and lowercase extension for a file located under the data directory. File contents are never returned.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description:
              'Path to a file under the data directory, expressed relative to it. Absolute paths and traversal sequences (e.g. "..") are not permitted.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

function safeRelative(input) {
  const resolved = path.resolve(DATA_DIR, input);
  const rel = path.relative(DATA_DIR, resolved);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error(`Path traversal not allowed: ${input}`);
  }
  return { resolved, rel };
}

export async function callTool(name, args) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const a = args && typeof args === 'object' ? args : {};
  const knownKeys = Object.keys(a);
  if (knownKeys.length !== 1 || knownKeys[0] !== 'path') {
    throw new Error('Invalid arguments: only "path" is accepted');
  }
  if (typeof a.path !== 'string') {
    throw new Error('path must be a string');
  }
  if (a.path.length === 0) {
    throw new Error('path must not be empty');
  }

  const { resolved, rel } = safeRelative(a.path);

  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`File not found: ${a.path}`);
    }
    throw err;
  }
  if (!stat.isFile()) {
    throw new Error(`Not a regular file: ${a.path}`);
  }

  const ext = path.extname(rel).toLowerCase();
  const text =
    `path: ${rel}\n` +
    `size: ${stat.size} bytes\n` +
    `extension: ${ext}`;

  return {
    content: [{ type: 'text', text }]
  };
}

