import { listTools, callTool } from './server.mjs';

const tools = await listTools();
console.log('listTools ok, count=', tools.length);
console.log('strict schema:', JSON.stringify(tools[0].inputSchema));

// happy path
console.log('metadata:', JSON.stringify(await callTool('file_metadata', {path: 'readme.txt'})));
console.log('metadata config.json:', JSON.stringify(await callTool('file_metadata', {path: 'config.json'})));

