try { await callTool('nope', {}); console.log('FAIL: unknown tool did not throw'); }
catch (e) { console.log('unknown tool rejected:', e.message); }

// traversal
try { await callTool('file_metadata', {path: '../server.mjs'}); console.log('FAIL: traversal not rejected'); }
catch (e) { console.log('traversal rejected:', e.message); }

// missing file
try { await callTool('file_metadata', {path: 'nope.txt'}); console.log('FAIL: missing not rejected'); }
catch (e) { console.log('missing rejected:', e.message); }

// extra arg
try { await callTool('file_metadata', {path: 'readme.txt', extra: 1}); console.log('FAIL: extra arg accepted'); }
catch (e) { console.log('extra arg rejected:', e.message); }

// missing path
try { await callTool('file_metadata', {}); console.log('FAIL: missing path accepted'); }
catch (e) { console.log('missing path rejected:', e.message); }

// absolute path
try { await callTool('file_metadata', {path: '/etc/passwd'}); console.log('FAIL: absolute accepted'); }
